def impReplaceIff (hp : �� ⊢ φ₁ ⭤ φ₂) (hq : �� ⊢ ψ₁ ⭤ ψ₂) : �� ⊢ (φ₁ ➝ ψ₁) ⭤ (φ₂ ➝ ψ₂) := by
  apply iffIntro;
  . apply deduct'; exact impTrans'' (of $ and₂' hp) $ impTrans'' (FiniteContext.id) (of $ and₁' hq);
