lemma iff_imply_left_cons_conj'! : �� ⊢! ⋀(φ :: Γ) ➝ ψ ↔ �� ⊢! φ ⋏ ⋀Γ ➝ ψ := by
  induction Γ with
  | nil =>
    simp [and_imply_iff_imply_imply'!];
    constructor;
    . intro h; apply imp_swap'!; exact imply₁'! h;
    . intro h; exact imp_swap'! h ⨀ verum!;
  | cons ψ ih => simp;

def implyConj' (φ : F) (Γ : List F) (b : (ψ : F) → ψ ∈ Γ → �� ⊢ φ ➝ ψ) : �� ⊢ φ ➝ ⋀Γ :=
  match Γ with
  | []     => imply₁' verum
  | [ψ]    => by apply b; simp;
  | ψ :: χ :: Γ => by
    simp;
    apply implyAnd (b ψ (by simp)) (implyConj' φ _ (fun ψ hq ↦ b ψ (by simp [hq])));

