lemma id_conj! (he : ∀ g ∈ Γ, g = φ) : �� ⊢! φ ➝ ⋀Γ := by
  induction Γ using List.induction_with_singleton with
  | hcons χ Γ h ih =>
    simp_all;
    have ⟨he₁, he₂⟩ := he; subst he₁;
    exact imply_right_and! imp_id! ih;
  | _ => simp_all;

